"use client";

import { useMemo, useState } from "react";
import { motion } from "framer-motion";
import { Search, X, MapPin, Tag, Calendar, ExternalLink, ChevronRight, Lock, Info, Scale, BookOpen } from "lucide-react";
import { Button } from "@/components/ui/Button";
import preview from "@/data/public-record-preview.json";

// Real Ugandan legislation and judgments (Laws.Africa / ULII), generated by scripts/build-record-preview.mjs.
type PublicRecord = (typeof preview.records)[number];

const RECORDS: PublicRecord[] = preview.records;
const FREE_RESULTS = 5;

// Jurisdictions on the roadmap; only those with records in the preview are selectable.
const JURISDICTIONS = ["Uganda", "Kenya", "Tanzania", "Rwanda", "Burundi", "Nigeria", "South Africa"];
const TYPES = ["All Types", "Legislation", "Judgment"] as const;
type SortKey = "relevance" | "newest" | "oldest";

const formatDate = (iso: string) =>
  iso ? new Date(`${iso}T00:00:00Z`).toLocaleDateString("en-GB", { day: "numeric", month: "short", year: "numeric", timeZone: "UTC" }) : "";

const terms = (q: string) => q.toLowerCase().split(/\s+/).filter((t) => t.length > 1);

/** Simple relevance: title matches count most, then subtitle/topic, then snippet. */
function score(r: PublicRecord, words: string[]) {
  if (words.length === 0) return 1;
  const title = r.title.toLowerCase();
  const meta = `${r.subtitle} ${r.topic}`.toLowerCase();
  const body = r.snippet.toLowerCase();
  return words.reduce((s, w) => s + (title.includes(w) ? 3 : 0) + (meta.includes(w) ? 2 : 0) + (body.includes(w) ? 1 : 0), 0);
}

interface SearchInterfaceProps {
  query: string;
  initialJurisdiction?: string;
  onClose: () => void;
}

export function SearchInterface({ query, initialJurisdiction = "Uganda", onClose }: SearchInterfaceProps) {
  const [input, setInput] = useState(query);
  const [activeQuery, setActiveQuery] = useState(query);
  const [jurisdiction, setJurisdiction] = useState(initialJurisdiction);
  const [type, setType] = useState<(typeof TYPES)[number]>("All Types");
  const [sort, setSort] = useState<SortKey>("relevance");

  const available = useMemo(() => new Set(RECORDS.map((r) => r.jurisdiction)), []);
  const jurisdictionAvailable = available.has(jurisdiction);

  const results = useMemo(() => {
    if (!jurisdictionAvailable) return [];
    const words = terms(activeQuery);
    return RECORDS.filter((r) => r.jurisdiction === jurisdiction && (type === "All Types" || r.type === type))
      .map((r) => ({ r, s: score(r, words) }))
      .filter(({ s }) => s > 0)
      .sort((a, b) =>
        sort === "newest" ? b.r.date.localeCompare(a.r.date)
        : sort === "oldest" ? a.r.date.localeCompare(b.r.date)
        : b.s - a.s || b.r.date.localeCompare(a.r.date)
      )
      .map(({ r }) => r);
  }, [activeQuery, jurisdiction, type, sort, jurisdictionAvailable]);

  const typeCounts = useMemo(() => {
    const words = terms(activeQuery);
    const inScope = RECORDS.filter((r) => r.jurisdiction === jurisdiction && score(r, words) > 0);
    return {
      "All Types": inScope.length,
      Legislation: inScope.filter((r) => r.type === "Legislation").length,
      Judgment: inScope.filter((r) => r.type === "Judgment").length,
    };
  }, [activeQuery, jurisdiction]);

  const visible = results.slice(0, FREE_RESULTS);
  const locked = results.length - visible.length;

  const goToWaitlist = () => {
    onClose();
    setTimeout(() => document.getElementById("waitlist")?.scrollIntoView({ behavior: "smooth" }), 50);
  };

  const resetFilters = () => {
    setJurisdiction("Uganda");
    setType("All Types");
    setInput("");
    setActiveQuery("");
  };

  const jurisdictionButton = (j: string, compact = false) => {
    const enabled = available.has(j);
    const active = jurisdiction === j;
    return (
      <button
        key={j}
        type="button"
        disabled={!enabled}
        onClick={() => setJurisdiction(j)}
        className={`${compact ? "shrink-0 px-3 py-1.5 text-xs" : "w-full px-3 py-2 text-sm"} text-left transition-colors flex items-center justify-between gap-2 ${
          active ? "bg-accent text-white font-bold" : enabled ? "text-black/70 hover:bg-black/5" : "text-black/30 cursor-not-allowed"
        }`}
        title={enabled ? undefined : "Coming soon"}
      >
        {j}
        {!enabled && <span className="text-[11px] font-semibold uppercase tracking-wider">Soon</span>}
        {active && !compact && <ChevronRight className="h-3 w-3" />}
      </button>
    );
  };

  return (
    <div className="fixed inset-0 z-[100] bg-white flex flex-col overflow-hidden" role="dialog" aria-modal="true" aria-label="Search public records">
      {/* Search Header */}
      <header className="border-b border-black/10 px-4 sm:px-6 py-4 bg-white">
        <form
          className="flex items-center gap-3 max-w-4xl mx-auto w-full"
          onSubmit={(e) => {
            e.preventDefault();
            setActiveQuery(input);
          }}
        >
          <div className="relative grow">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-black/20" aria-hidden />
            <input
              type="search"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Search Ugandan laws and judgments…"
              aria-label="Search records"
              className="w-full pl-12 pr-4 py-3 bg-[#f0f1f4] text-black outline-none font-medium placeholder:text-black/30"
              autoFocus
            />
          </div>
          <Button type="submit" size="sm" className="shrink-0 hidden sm:inline-flex">Search</Button>
          <Button type="button" variant="outline" size="sm" onClick={onClose} className="shrink-0 flex items-center gap-2">
            <X className="h-4 w-4" />
            <span className="hidden sm:inline">Close</span>
          </Button>
        </form>

        {/* Mobile filters: horizontal chips */}
        <div className="md:hidden mt-3 flex gap-1 overflow-x-auto -mx-4 px-4">
          {JURISDICTIONS.map((j) => jurisdictionButton(j, true))}
        </div>
        <div className="md:hidden mt-2 flex gap-1">
          {TYPES.map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setType(t)}
              className={`px-3 py-1.5 text-xs ${type === t ? "bg-[#212429] text-white font-bold" : "text-black/70 bg-black/5"}`}
            >
              {t} ({typeCounts[t]})
            </button>
          ))}
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar Filters */}
        <aside className="w-64 border-r border-black/10 p-6 hidden md:block overflow-y-auto bg-[#fafbfc]">
          <div className="space-y-8">
            <div>
              <h3 className="text-xs font-bold uppercase tracking-widest text-black/40 mb-4 flex items-center gap-2">
                <MapPin className="h-3 w-3" />
                Jurisdiction
              </h3>
              <div className="space-y-1">{JURISDICTIONS.map((j) => jurisdictionButton(j))}</div>
            </div>

            <div>
              <h3 className="text-xs font-bold uppercase tracking-widest text-black/40 mb-4 flex items-center gap-2">
                <Tag className="h-3 w-3" />
                Document Type
              </h3>
              <div className="space-y-1">
                {TYPES.map((t) => (
                  <button
                    key={t}
                    type="button"
                    onClick={() => setType(t)}
                    className={`w-full text-left px-3 py-2 text-sm transition-colors flex items-center justify-between ${
                      type === t ? "bg-accent text-white font-bold" : "text-black/70 hover:bg-black/5"
                    }`}
                  >
                    {t}
                    <span className={`text-xs tabular-nums ${type === t ? "text-white/80" : "text-black/40"}`}>{typeCounts[t]}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="pt-8 border-t border-black/10">
              <Button variant="outline" className="w-full text-xs font-bold py-2 h-auto" onClick={resetFilters}>
                Clear All Filters
              </Button>
            </div>
          </div>
        </aside>

        {/* Results Main Area */}
        <main className="flex-1 overflow-y-auto bg-white p-4 sm:p-6 md:p-10">
          <div className="max-w-4xl mx-auto">
            {/* Honest preview notice */}
            <div className="mb-6 flex items-start gap-3 bg-[#f0f1f4] p-4 text-sm text-black/70">
              <Info className="h-4 w-4 shrink-0 mt-0.5 text-accent" aria-hidden />
              <p>
                <strong className="text-black">Preview:</strong> you are searching a sample of {RECORDS.length} real Ugandan laws
                and court judgments, refreshed {formatDate(preview.generatedAt)}. Full Public Record search across gazettes,
                filings and more countries is launching soon.
              </p>
            </div>

            <div className="flex flex-wrap items-center justify-between gap-3 mb-6">
              <div>
                <h2 className="text-sm font-bold text-black/40 uppercase tracking-widest">
                  {results.length} {results.length === 1 ? "record" : "records"}
                </h2>
                {activeQuery && (
                  <p className="mt-1 text-black font-medium">
                    Results for &quot;<span className="text-accent">{activeQuery}</span>&quot;
                  </p>
                )}
              </div>
              <label className="flex items-center gap-2 text-xs text-black/50">
                Sort by
                <select
                  value={sort}
                  onChange={(e) => setSort(e.target.value as SortKey)}
                  className="bg-transparent border border-black/10 text-xs font-bold px-3 py-1.5 outline-none text-black"
                >
                  <option value="relevance">Most relevant</option>
                  <option value="newest">Newest first</option>
                  <option value="oldest">Oldest first</option>
                </select>
              </label>
            </div>

            {!jurisdictionAvailable ? (
              <div className="flex flex-col items-center justify-center py-20 text-center">
                <MapPin className="h-10 w-10 text-black/20 mb-4" />
                <h3 className="text-xl font-bold text-black mb-2">{jurisdiction} is coming soon</h3>
                <p className="text-black/50 max-w-md mx-auto">
                  Join the waitlist and tell us you need {jurisdiction}. We prioritise new jurisdictions by demand.
                </p>
                <Button className="mt-8" onClick={goToWaitlist}>Join the waitlist</Button>
              </div>
            ) : results.length > 0 ? (
              <div className="space-y-4">
                {visible.map((r, idx) => (
                  <motion.article
                    key={r.id}
                    initial={{ opacity: 0, y: 12 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: idx * 0.04 }}
                    className="group border border-black/10 p-5 sm:p-6 hover:border-accent/40 transition-colors"
                  >
                    <div className="flex flex-wrap items-center gap-3 mb-3 text-[11px] font-bold uppercase tracking-widest">
                      <span className="flex items-center gap-1.5 bg-accent/5 text-accent px-2 py-0.5">
                        {r.type === "Judgment" ? <Scale className="h-3 w-3" aria-hidden /> : <BookOpen className="h-3 w-3" aria-hidden />}
                        {r.type}
                      </span>
                      <span className="flex items-center gap-1.5 text-black/40"><MapPin className="h-3 w-3" aria-hidden />{r.jurisdiction}</span>
                      {r.date && <span className="flex items-center gap-1.5 text-black/40"><Calendar className="h-3 w-3" aria-hidden />{formatDate(r.date)}</span>}
                      <span className="text-black/40">#{r.topic}</span>
                    </div>
                    <h3 className="text-lg sm:text-xl font-bold text-black leading-snug">{r.title}</h3>
                    {r.subtitle && <p className="mt-1 text-sm font-medium text-black/50">{r.subtitle}</p>}
                    <p className="mt-3 text-black/60 text-sm leading-relaxed max-w-3xl">{r.snippet}</p>
                    <a
                      href={r.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="mt-4 inline-flex items-center gap-2 text-sm font-semibold text-black hover:text-accent transition-colors"
                    >
                      Read full text on {r.source}
                      <ExternalLink className="h-3.5 w-3.5" aria-hidden />
                    </a>
                  </motion.article>
                ))}

                {/* Gate, like a tender portal: the rest of the matches unlock with full access */}
                {locked > 0 && (
                  <div className="relative border border-dashed border-black/20 p-6 sm:p-8 text-center bg-[#fafbfc]">
                    <Lock className="h-6 w-6 mx-auto text-accent" aria-hidden />
                    <h3 className="mt-3 text-lg font-bold text-black">
                      {locked} more matching {locked === 1 ? "record" : "records"}
                    </h3>
                    <p className="mt-2 text-sm text-black/60 max-w-md mx-auto">
                      Full access unlocks every result, gazettes and filings, more countries, saved searches and
                      alerts when new records match.
                    </p>
                    <Button className="mt-6" onClick={goToWaitlist}>Get full access: join the waitlist</Button>
                  </div>
                )}
              </div>
            ) : (
              <div className="flex flex-col items-center justify-center py-20 text-center">
                <div className="bg-[#f0f1f4] p-6 rounded-full mb-6">
                  <Search className="h-10 w-10 text-black/20" aria-hidden />
                </div>
                <h3 className="text-xl font-bold text-black mb-2">No records in the preview match</h3>
                <p className="text-black/50 max-w-md mx-auto">
                  The preview covers tax, land, elections, data protection, companies, procurement, employment,
                  corruption, cybercrime and banking. Try one of those, or join the waitlist for the full archive.
                </p>
                <div className="mt-8 flex flex-wrap justify-center gap-3">
                  <Button variant="outline" onClick={resetFilters}>Clear search</Button>
                  <Button onClick={goToWaitlist}>Join the waitlist</Button>
                </div>
              </div>
            )}

            <p className="mt-10 text-xs text-black/40 leading-relaxed">
              Records via the{" "}
              <a href="https://laws.africa" target="_blank" rel="noopener noreferrer" className="underline">Laws.Africa</a>{" "}
              Legal Knowledge Platform. Excerpts are shown for search; the full, authoritative text is on{" "}
              <a href="https://ulii.org" target="_blank" rel="noopener noreferrer" className="underline">ULII</a>.
            </p>
          </div>
        </main>
      </div>
    </div>
  );
}
